node --input-type=module -e "
import { executeWorkflowAsync } from './src/engine.js';

const wf = (op, retry) => ({
  id: 'w', entry: 'a',
  nodes: [
    { id: 'a', type: 'action', operation: op, ...(retry ? { retry } : {}), next: 'b' },
    { id: 'b', type: 'action', message: 'later', next: 'end' },
    { id: 'end', type: 'end' },
  ],
});
const retry = { attempts: 3, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };

// 1. Error with message mutated to null -> must be a failure, not success
let r = await executeWorkflowAsync(wf('bad', retry), {}, { bad: () => { const e = new Error('x'); e.message = null; throw e; } });
console.log('1:', r.status, JSON.stringify(r.error), 'attempts:', r.actionAttempts.length, 'b output:', JSON.stringify(r.context.output.b));

// 2. Error with empty-string message -> still a failure
r = await executeWorkflowAsync(wf('empty'), {}, { empty: () => { throw new Error(''); } });
console.log('2:', r.status, JSON.stringify(r.error), 'ok-flag of record:', r.actionAttempts[0].ok, 'error:', JSON.stringify(r.actionAttempts[0].error));

// 3. Throwing message getter -> placeholder, run not rejected
r = await executeWorkflowAsync(wf('getter', retry), {}, { getter: () => { throw Object.create(Error.prototype, { message: { get() { throw new Error('boom'); } } }); } });
console.log('3:', r.status, JSON.stringify(r.error), 'attempts:', r.actionAttempts.length);

// 4. Object.create(null) thrown -> String() throws -> placeholder
r = await executeWorkflowAsync(wf('nonstr'), {}, { nonstr: () => { throw Object.create(null); } });
console.log('4:', r.status, JSON.stringify(r.error));

// 5. Primitives keep their text
for (const v of ['oops', 42, true, null, undefined]) {
  r = await executeWorkflowAsync(wf('p'), {}, { p: () => { throw v; } });
  console.log('5:', JSON.stringify(v), '->', r.status, JSON.stringify(r.error));
}

// 6. Retry-then-succeed still works after weird failures
let calls = 0;
r = await executeWorkflowAsync(wf('flaky', retry), {}, { flaky: () => { calls += 1; if (calls < 3) { const e = new Error('x'); e.message = null; throw e; } return { done: true }; } });
console.log('6:', r.status, 'attempts:', r.actionAttempts.length, 'errors:', r.actionAttempts.map(a => JSON.stringify(a.error)).join(','), 'output:', JSON.stringify(r.context.output.a));
"

node --input-type=module -e "
import { executeWorkflowAsync } from './src/engine.js';

const wf = {
  id: 'w', entry: 'a',
  nodes: [
    { id: 'a', type: 'action', operation: 'opA', compensation: { operation: 'undoA', retry: { attempts: 2, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 } }, next: 'b' },
    { id: 'b', type: 'action', operation: 'opB', compensation: { operation: 'undoB' }, next: 'c' },
    { id: 'c', type: 'action', operation: 'opC', next: 'end' },
    { id: 'end', type: 'end' },
  ],
};

// undoB (runs first, reverse order) throws an unreadable error; undoA throws null-message Error.
// Both must be recorded as failed with their own retry configs, and neither may skip the other.
const r = await executeWorkflowAsync(wf, {}, {
  opA: () => 'A-out',
  opB: () => 'B-out',
  opC: () => { throw Object.create(null); },
  undoA: () => { const e = new Error('x'); e.message = 123; throw e; },
  undoB: () => { throw Object.create(null); },
});
console.log('status:', r.status, '| error:', JSON.stringify(r.error));
console.log('compensationStatus:', r.compensationStatus);
console.log('outputs preserved:', JSON.stringify(r.context.output));
for (const a of r.compensationAttempts) {
  console.log(' comp:', a.nodeId, 'attempt', a.attempt, 'ok:', a.ok, 'error:', JSON.stringify(a.error));
}

// Compensation succeeding normally still yields completed
const r2 = await executeWorkflowAsync(wf, {}, {
  opA: () => 'A', opB: () => 'B',
  opC: () => { throw new Error('fail'); },
  undoA: () => 'undone-A', undoB: () => undefined,
});
console.log('all-ok:', r2.compensationStatus, r2.compensationAttempts.map(a => a.ok + '/' + JSON.stringify(a.result)).join(' '));
"
